Here are two common ways to turn a CameraImage (from the camera package) into PNG bytes. It handles both BGRA8888 (iOS) and YUV420 (most Android).

Option A: Pure Dart (no native plugin), using package:image for PNG encoding
- Works everywhere, but YUV → RGB in Dart can be CPU-heavy on large frames.

Dependencies:
- camera
- image: ^4.1.7 (or latest)

Code:
import 'dart:typed_data';
import 'package:camera/camera.dart';
import 'package:image/image.dart' as img;

Future<Uint8List> cameraImageToPng(CameraImage image) async {
  if (image.format.group == ImageFormatGroup.bgra8888) {
    // iOS typically BGRA8888
    final plane = image.planes[0];
    // Build an RGBA image for the encoder
    final rgba = Uint8List(image.width * image.height * 4);
    // Convert BGRA -> RGBA
    for (int i = 0, j = 0; i < plane.bytes.length; i += 4, j += 4) {
      final b = plane.bytes[i];
      final g = plane.bytes[i + 1];
      final r = plane.bytes[i + 2];
      final a = plane.bytes[i + 3];
      rgba[j] = r;
      rgba[j + 1] = g;
      rgba[j + 2] = b;
      rgba[j + 3] = a;
    }
    final out = img.Image.fromBytes(
      width: image.width,
      height: image.height,
      bytes: rgba.buffer,
      numChannels: 4,
      order: img.ChannelOrder.rgba,
    );
    return Uint8List.fromList(img.encodePng(out));
  }

  // Assume YUV420 (Android)
  if (image.format.group == ImageFormatGroup.yuv420) {
    final width = image.width;
    final height = image.height;

    final yPlane = image.planes[0];
    final uPlane = image.planes[1];
    final vPlane = image.planes[2];

    final yRowStride = yPlane.bytesPerRow;
    final uvRowStride = uPlane.bytesPerRow;
    final uvPixelStride = uPlane.bytesPerPixel ?? 1;

    final rgba = Uint8List(width * height * 4);

    int rgbaIndex = 0;
    for (int y = 0; y < height; y++) {
      final yRow = yRowStride * y;
      final uvRow = uvRowStride * (y >> 1);
      for (int x = 0; x < width; x++) {
        final yIndex = yRow + x;

        // U/V are subsampled 2x2
        final uvIndex = uvRow + (x >> 1) * uvPixelStride;

        final Y = yPlane.bytes[yIndex];
        final U = uPlane.bytes[uvIndex];
        final V = vPlane.bytes[uvIndex];

        // Convert YUV -> RGB (BT.601)
        final yVal = Y.toDouble();
        final uVal = U - 128.0;
        final vVal = V - 128.0;

        int r = (yVal + 1.402 * vVal).round();
        int g = (yVal - 0.344136 * uVal - 0.714136 * vVal).round();
        int b = (yVal + 1.772 * uVal).round();

        if (r < 0) r = 0; else if (r > 255) r = 255;
        if (g < 0) g = 0; else if (g > 255) g = 255;
        if (b < 0) b = 0; else if (b > 255) b = 255;

        rgba[rgbaIndex++] = r;
        rgba[rgbaIndex++] = g;
        rgba[rgbaIndex++] = b;
        rgba[rgbaIndex++] = 255; // alpha
      }
    }

    final out = img.Image.fromBytes(
      width: width,
      height: height,
      bytes: rgba.buffer,
      numChannels: 4,
      order: img.ChannelOrder.rgba,
    );
    return Uint8List.fromList(img.encodePng(out));
  }

  throw UnsupportedError('Unsupported CameraImage format: ${image.format.group}');
}

Notes:
- If your preview or image is rotated/mirrored, rotate or flip using package:image before encoding:
  // Example: rotate 90 degrees clockwise
  final rotated = img.copyRotate(out, angle: 90);
  final png = Uint8List.fromList(img.encodePng(rotated));

Option B: Faster YUV conversion using native libyuv
- Use flutter_libyuv (or similar) to convert YUV420 to RGBA quickly, then encode PNG with package:image.

Example (conceptual):
import 'package:flutter_libyuv/flutter_libyuv.dart' as ly;
import 'package:image/image.dart' as img;

Future<Uint8List> cameraImageToPngFast(CameraImage image) async {
  if (image.format.group == ImageFormatGroup.yuv420) {
    final rgba = await ly.yuv420ToRgba(
      image.planes[0].bytes,
      image.planes[1].bytes,
      image.planes[2].bytes,
      image.width,
      image.height,
      image.planes[0].bytesPerRow,
      image.planes[1].bytesPerRow,
      image.planes[2].bytesPerRow,
      image.planes[1].bytesPerPixel ?? 1,
    );
    final out = img.Image.fromBytes(
      width: image.width,
      height: image.height,
      bytes: rgba.buffer,
      numChannels: 4,
      order: img.ChannelOrder.rgba,
    );
    return Uint8List.fromList(img.encodePng(out));
  }
  // For BGRA8888, same as Option A’s BGRA path.
  return cameraImageToPng(image);
}

Pick Option A for simplicity, Option B for speed on Android.

